package com.collectionselection;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

import java.awt.Color;

@ConfigGroup("collectionselection")
public interface CollectionSelectionConfig extends Config
{
	@ConfigItem(
		keyName = "showChatMessage",
		name = "Chat notifications",
		description = "Show a chat message when a page locks, unlocks, or a pet is received",
		position = 1
	)
	default boolean showChatMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTargetOverlay",
		name = "Target overlay",
		description = "Show a small card on the gameframe displaying your selected target",
		position = 2
	)
	default boolean showTargetOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showClogPopup",
		name = "Collection log popup",
		description = "Show a native-style popup for non-target collection log additions",
		position = 3
	)
	default boolean showClogPopup()
	{
		return true;
	}

	// ── Fire Settings ─────────────────────────────────────────────────────────

	@ConfigSection(
		name = "Fire Settings",
		description = "Tune the fire / glow animation",
		position = 10
	)
	String fireSection = "fire";

	@Range(min = 1, max = 20)
	@ConfigItem(
		keyName = "fireSpeed",
		name = "Animation Speed",
		description = "Higher values = faster fire / glow animation",
		section = "fire",
		position = 11
	)
	default int fireSpeed()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "fireGlowColor",
		name = "Glow Colour",
		description = "Base colour used for the fire outline",
		section = "fire",
		position = 12
	)
	default Color fireGlowColor()
	{
		return new Color(220, 60, 0);
	}
}

package com.collectionselection;

import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

import javax.inject.Inject;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.image.BufferedImage;

/**
 * Draws overlays directly on collection log item widgets using WidgetItemOverlay.
 *
 * Verified widget IDs (Group 621):
 *   Child 12 — Bosses list     (dynamic children = entry name labels)
 *   Child 16 — Raids list
 *   Child 32 — Clues list
 *   Child 34 — Other list
 *   Child 35 — Minigames list
 *   Child 20 — header label    (dynamic child [0] = current entry title)
 *   Child 37 — Items panel     (dynamic children = item slots)
 */
public class CollectionSelectionOverlay extends WidgetItemOverlay
{
	static final int CLOG_GROUP       = 621;
	static final int CLOG_ITEMS_PANEL = 37;
	static final int CLOG_HEADER      = 20;

	static final int[] CLOG_LIST_CHILDREN = {12, 16, 32, 34, 35};

	private final CollectionSelectionPlugin plugin;
	private final CollectionSelectionConfig config;
	private final Client                    client;
	private final ItemManager               itemManager;
	private final BufferedImage             lockIcon;
	private final BufferedImage             listLockIcon;

	@Inject
	public CollectionSelectionOverlay(CollectionSelectionPlugin plugin, CollectionSelectionConfig config,
	                                  Client client, ItemManager itemManager)
	{
		this.plugin      = plugin;
		this.config      = config;
		this.client      = client;
		this.itemManager = itemManager;
		drawAfterInterface(CLOG_GROUP);

		BufferedImage icon = null;
		try
		{
			icon = ImageUtil.loadImageResource(getClass(), "/locked_icon.png");
		}
		catch (Exception ignored) {}
		lockIcon = icon;

		BufferedImage listIcon = null;
		try
		{
			listIcon = ImageUtil.loadImageResource(getClass(), "/locked_list.png");
		}
		catch (Exception ignored) {}
		listLockIcon = listIcon;
	}

	/**
	 * Draws the padlock icon flush to the right edge of every locked list entry
	 * (clipped to the list widget bounds to prevent icons floating when scrolled),
	 * then delegates item-slot overlays.
	 */
	@Override
	public Dimension render(Graphics2D g)
	{
		if (listLockIcon != null)
		{
			for (int childId : CLOG_LIST_CHILDREN)
			{
				Widget list = client.getWidget(CLOG_GROUP, childId);
				if (list == null || list.isHidden()) continue;

				Widget[] children = list.getDynamicChildren();
				if (children == null) continue;

				// The list widget is the scrollable content widget — its parent is the
				// stable scroll-container representing the actual visible area on screen.
				Widget viewport = list.getParent() != null ? list.getParent() : list;
				net.runelite.api.Point vpLoc = viewport.getCanvasLocation();
				if (vpLoc == null) continue;

				int vpX0 = vpLoc.getX();
				int vpY0 = vpLoc.getY();
				int vpY1 = vpY0 + viewport.getHeight();

				Shape prevClip = g.getClip();
				g.clip(new Rectangle(vpX0, vpY0, viewport.getWidth(), viewport.getHeight()));

				for (Widget child : children)
				{
					if (child.isHidden()) continue;

					String text = net.runelite.client.util.Text.removeTags(child.getText()).trim();
					if (text.isEmpty()) continue;

					CollectionSelectionPlugin.TargetEntry entry = plugin.targets.get(text);
					if (entry == null || !entry.locked) continue;

					net.runelite.api.Point loc = child.getCanvasLocation();
					if (loc == null) continue;

					int childY0 = loc.getY();
					int childY1 = childY0 + child.getHeight();
					if (childY1 <= vpY0 || childY0 >= vpY1) continue;

					int iconSize = Math.min(child.getHeight() - 2, 12);
					int x = loc.getX() + child.getWidth() - iconSize - 1;
					int y = loc.getY() + (child.getHeight() - iconSize) / 2;

					g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
					g.drawImage(listLockIcon, x, y, iconSize, iconSize, null);
				}

				g.setClip(prevClip);
			}
		}

		return super.render(g);
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		Widget w = widgetItem.getWidget();
		if (w == null) return;
		Widget parent = w.getParent();
		if (parent == null || WidgetUtil.componentToId(parent.getId()) != CLOG_ITEMS_PANEL) return;

		String entryName = plugin.currentEntryName;
		if (entryName == null) return;

		CollectionSelectionPlugin.TargetEntry entry = plugin.targets.get(entryName);
		Rectangle bounds = widgetItem.getCanvasBounds();

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		if (entry != null && entry.locked)
		{
			if (w.getOpacity() > 0)
			{
				drawLockedTint(g, bounds, itemId);
				drawLockIcon(g, bounds);
			}
		}
		else if (entry != null && entry.itemId == itemId)
		{
			drawShapeFire(g, bounds, itemId);
		}
	}

	// ── Target outline: shape fire ────────────────────────────────────────────

	/** Flickering fire outline that follows the item's exact pixel silhouette. */
	private void drawShapeFire(Graphics2D g, Rectangle bounds, int itemId)
	{
		BufferedImage itemImg = itemManager.getImage(itemId);
		if (itemImg == null)
		{
			drawFire(g, bounds);
			return;
		}

		double flicker = pulse((long)(120 * config.fireSpeed()));
		Color  base    = config.fireGlowColor();
		int    expand  = 2;
		int    w       = bounds.width  + expand * 2;
		int    h       = bounds.height + expand * 2;

		BufferedImage halo = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D hg = halo.createGraphics();
		hg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		for (int dx = 0; dx <= expand * 2; dx++)
		{
			for (int dy = 0; dy <= expand * 2; dy++)
			{
				if (dx == expand && dy == expand) continue;
				hg.drawImage(itemImg, dx, dy, bounds.width, bounds.height, null);
			}
		}

		hg.setComposite(AlphaComposite.SrcIn);
		hg.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), (int)(160 + 95 * flicker)));
		hg.fillRect(0, 0, w, h);

		hg.setComposite(AlphaComposite.DstOut);
		hg.drawImage(itemImg, expand, expand, bounds.width, bounds.height, null);
		hg.dispose();

		g.drawImage(halo, bounds.x - expand, bounds.y - expand, null);
	}

	/** Fallback fire border used when item image is unavailable. */
	private void drawFire(Graphics2D g, Rectangle bounds)
	{
		double flicker = pulse((long)(120 * config.fireSpeed()));
		Color  base    = config.fireGlowColor();

		float sw = 1.5f + (float)(1.5 * flicker);
		g.setStroke(new BasicStroke(sw, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), (int)(160 + 95 * flicker)));
		g.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 2, bounds.height - 2);

		Color bright = base.brighter();
		g.setStroke(new BasicStroke(1f));
		g.setColor(new Color(bright.getRed(), bright.getGreen(), bright.getBlue(), (int)(80 + 120 * flicker)));
		g.drawRect(bounds.x + 2, bounds.y + 2, bounds.width - 4, bounds.height - 4);
	}

	// ── Lock style: padlock ───────────────────────────────────────────────────

	/** Dark breathing tint masked to the item's own pixel shape. */
	private void drawLockedTint(Graphics2D g, Rectangle bounds, int itemId)
	{
		double pulse = pulse(1400);
		int alpha = (int)(80 + 45 * pulse);

		BufferedImage itemImg = itemManager.getImage(itemId);
		if (itemImg != null)
		{
			BufferedImage temp = new BufferedImage(bounds.width, bounds.height, BufferedImage.TYPE_INT_ARGB);
			Graphics2D tg = temp.createGraphics();
			tg.setColor(new Color(0, 0, 0, alpha));
			tg.fillRect(0, 0, bounds.width, bounds.height);
			tg.setComposite(AlphaComposite.DstIn);
			tg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			tg.drawImage(itemImg, 0, 0, bounds.width, bounds.height, null);
			tg.dispose();
			g.drawImage(temp, bounds.x, bounds.y, null);
		}
		else
		{
			g.setColor(new Color(0, 0, 0, alpha));
			g.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
		}

		if (itemImg != null)
		{
			BufferedImage vig = new BufferedImage(bounds.width, bounds.height, BufferedImage.TYPE_INT_ARGB);
			Graphics2D vg = vig.createGraphics();
			float cx = bounds.width  * 0.5f;
			float cy = bounds.height * 0.5f;
			float r  = Math.max(bounds.width, bounds.height) * 0.7f;
			vg.setPaint(new RadialGradientPaint(cx, cy, r,
				new float[]{0f, 1f},
				new Color[]{new Color(0, 0, 0, 0), new Color(0, 0, 0, 90)}));
			vg.fillRect(0, 0, bounds.width, bounds.height);
			vg.setComposite(AlphaComposite.DstIn);
			vg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			vg.drawImage(itemImg, 0, 0, bounds.width, bounds.height, null);
			vg.dispose();
			g.drawImage(vig, bounds.x, bounds.y, null);
		}
	}

	/** Pulsing padlock icon centred on the item. */
	private void drawLockIcon(Graphics2D g, Rectangle bounds)
	{
		if (lockIcon == null) return;
		double pulse = pulse(1400);
		float alpha = 0.65f + 0.35f * (float) pulse;

		int size = Math.min(bounds.width, bounds.height) / 2;
		int x = bounds.x + (bounds.width  - size) / 2;
		int y = bounds.y + (bounds.height - size) / 2;

		Composite prev = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(lockIcon, x, y, size, size, null);
		g.setComposite(prev);
	}

	// ── Helpers ───────────────────────────────────────────────────────────────

	/** Smooth oscillation 0→1 over the given period in ms. */
	private double pulse(long periodMs)
	{
		return (Math.sin(System.currentTimeMillis() / (periodMs / Math.PI)) + 1.0) / 2.0;
	}
}

package com.collectionselection;

import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;

public class CollectionSelectionPanel extends PluginPanel
{
	// ── Palette ───────────────────────────────────────────────────────────────
	private static final Color COL_GOLD         = new Color(212, 175, 55);
	private static final Color COL_GOLD_BRIGHT  = new Color(255, 215,  0);
	private static final Color COL_GOLD_DIM     = new Color( 90,  72, 18);

	private static final Color COL_ACTIVE_STRIP = new Color(190, 150, 30);
	private static final Color COL_ACTIVE_SEL   = new Color( 46,  36, 10);
	private static final Color COL_ACTIVE_FG    = new Color(230, 215, 160);

	private static final Color COL_LOCKED_STRIP = new Color(160,  40, 40);
	private static final Color COL_LOCKED_SEL   = new Color( 52,  16, 16);
	private static final Color COL_LOCKED_FG    = new Color(220,  80, 80);

	private static final Color COL_ROW          = new Color( 30,  30, 30);
	private static final Color COL_ROW_HOV      = new Color( 42,  42, 42);
	private static final Color COL_ITEM_FG      = new Color(140, 133, 115);
	private static final Color COL_DIVIDER      = new Color( 45,  45, 45);
	private static final Color COL_HEADER_BG    = new Color( 14,  11,  3);
	private static final Color COL_SECTION_BG   = new Color( 22,  22, 22);

	private static final Color COL_BTN_COLLECT  = new Color(30,  70,  30);
	private static final Color COL_BTN_PET      = new Color(30,  50, 100);
	private static final Color COL_BTN_CLOG     = new Color(30,  60,  60);
	private static final Color COL_BTN_DISABLED = new Color(45,  45,  45);

	// ── State ─────────────────────────────────────────────────────────────────
	private JPanel entriesPanel;
	private final Map<JPanel, String> entryPanelMap = new LinkedHashMap<>();
	private final Set<String>         lockedNames   = new HashSet<>();
	private JPanel selectedRow       = null;
	private String selectedEntryName = null;

	// ── Fixed components ──────────────────────────────────────────────────────
	private final JTextField testItemField     = new JTextField();
	private final JButton    simulateCollectBtn;
	private final JButton    simulatePetBtn;
	private final JButton    simulateClogBtn;

	private Consumer<String> onSimulateCollect;
	private Runnable         onSimulatePet;
	private Consumer<String> onSimulateClogPopup;

	private final ImageIcon lockIconSmall;
	private JComponent      testSection;

	public CollectionSelectionPanel()
	{
		ImageIcon icon = null;
		try
		{
			BufferedImage img = ImageUtil.loadImageResource(getClass(), "/locked_icon.png");
			icon = new ImageIcon(img.getScaledInstance(10, 10, Image.SCALE_SMOOTH));
		}
		catch (Exception ignored) {}
		lockIconSmall = icon;

		simulateCollectBtn = createButton("SIMULATE COLLECT",    COL_BTN_COLLECT, COL_BTN_COLLECT.brighter());
		simulatePetBtn     = createButton("SIMULATE PET",        COL_BTN_PET,     COL_BTN_PET.brighter());
		simulateClogBtn    = createButton("SIMULATE CLOG POPUP", COL_BTN_CLOG,    COL_BTN_CLOG.brighter());

		setLayout(new BorderLayout(0, 0));
		setBackground(COL_HEADER_BG);

		testSection = buildTestSection();
		testSection.setVisible(false);

		add(buildHeader(), BorderLayout.NORTH);
		add(buildCenter(), BorderLayout.CENTER);
		add(testSection,   BorderLayout.SOUTH);
	}

	// ── Header ────────────────────────────────────────────────────────────────

	private JComponent buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout(0, 4))
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setPaint(new GradientPaint(0, 0, new Color(26, 20, 6), 0, getHeight(), COL_HEADER_BG));
				g2.fillRect(0, 0, getWidth(), getHeight());
				g2.setColor(new Color(COL_GOLD.getRed(), COL_GOLD.getGreen(), COL_GOLD.getBlue(), 180));
				g2.fillRect(0, 0, 2, getHeight());
				g2.fillRect(getWidth() - 2, 0, 2, getHeight());
				g2.setColor(COL_GOLD_DIM);
				g2.fillRect(0, getHeight() - 1, getWidth(), 1);
				g2.dispose();
			}
		};
		header.setOpaque(false);
		header.setBorder(new EmptyBorder(8, 10, 8, 10));

		Font titleFont = FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 13f);

		JLabel titleMain = new JLabel("COLLECTION SELECTIO");
		titleMain.setFont(titleFont);
		titleMain.setForeground(COL_GOLD_BRIGHT);

		// "N" — hidden dev-mode trigger, looks like plain title text
		JLabel titleN = new JLabel("N");
		titleN.setFont(titleFont);
		titleN.setForeground(COL_GOLD_BRIGHT);
		titleN.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				String pw = (String) JOptionPane.showInputDialog(
					CollectionSelectionPanel.this, null, "Dev Mode",
					JOptionPane.PLAIN_MESSAGE, null, null, null);
				if ("lockout".equals(pw))
				{
					testSection.setVisible(!testSection.isVisible());
					revalidate();
					repaint();
				}
			}
		});

		JPanel titleRow = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		titleRow.setOpaque(false);
		titleRow.add(titleMain);
		titleRow.add(titleN);

		header.add(titleRow, BorderLayout.NORTH);
		return header;
	}

	// ── Entry list ────────────────────────────────────────────────────────────

	private JComponent buildCenter()
	{
		entriesPanel = new JPanel();
		entriesPanel.setLayout(new BoxLayout(entriesPanel, BoxLayout.Y_AXIS));
		entriesPanel.setBackground(COL_ROW);
		entriesPanel.setBorder(BorderFactory.createMatteBorder(1, 0, 1, 0, COL_GOLD_DIM));

		JPanel center = new JPanel(new BorderLayout(0, 5));
		center.setBackground(COL_HEADER_BG);
		center.setBorder(new EmptyBorder(5, 4, 5, 4));
		center.add(entriesPanel, BorderLayout.CENTER);
		return center;
	}

	// ── Test section (dev-only) ───────────────────────────────────────────────

	private JComponent buildTestSection()
	{
		JLabel testLabel = new JLabel("TEST MODE", SwingConstants.CENTER);
		testLabel.setFont(FontManager.getRunescapeSmallFont());
		testLabel.setForeground(new Color(70, 70, 70));

		testItemField.setBackground(new Color(30, 30, 30));
		testItemField.setForeground(Color.LIGHT_GRAY);
		testItemField.setCaretColor(Color.WHITE);
		testItemField.setFont(FontManager.getRunescapeSmallFont());
		testItemField.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(55, 55, 55)),
			new EmptyBorder(2, 5, 2, 5)));

		simulateCollectBtn.addActionListener(e ->
		{
			String name = testItemField.getText().trim();
			if (!name.isEmpty() && onSimulateCollect != null) onSimulateCollect.accept(name);
		});
		simulatePetBtn.addActionListener(e ->
		{
			if (onSimulatePet != null) onSimulatePet.run();
		});
		simulateClogBtn.addActionListener(e ->
		{
			String name = testItemField.getText().trim();
			if (!name.isEmpty() && onSimulateClogPopup != null) onSimulateClogPopup.accept(name);
		});

		JPanel section = new JPanel(new GridLayout(5, 1, 0, 4));
		section.setBackground(new Color(18, 18, 18));
		section.setBorder(BorderFactory.createCompoundBorder(
			new MatteBorder(1, 0, 0, 0, new Color(50, 50, 50)),
			new EmptyBorder(7, 7, 7, 7)));
		section.add(testLabel);
		section.add(testItemField);
		section.add(simulateCollectBtn);
		section.add(simulatePetBtn);
		section.add(simulateClogBtn);
		return section;
	}

	// ── Callbacks ─────────────────────────────────────────────────────────────

	public void setOnSimulateCollect(Consumer<String> cb)  { this.onSimulateCollect  = cb; }
	public void setOnSimulatePet(Runnable cb)              { this.onSimulatePet      = cb; }
	public void setOnSimulateClogPopup(Consumer<String> cb){ this.onSimulateClogPopup = cb; }

	public String getSelectedEntryName() { return selectedEntryName; }

	// ── Data updates ──────────────────────────────────────────────────────────

	public void refresh(Map<String, CollectionSelectionPlugin.TargetEntry> targets, boolean hasPetCredit)
	{
		SwingUtilities.invokeLater(() ->
		{
			lockedNames.clear();
			entryPanelMap.clear();
			selectedRow       = null;
			selectedEntryName = null;
			entriesPanel.removeAll();

			List<CollectionSelectionPlugin.TargetEntry> active = new ArrayList<>();
			List<CollectionSelectionPlugin.TargetEntry> locked = new ArrayList<>();

			for (CollectionSelectionPlugin.TargetEntry e : targets.values())
			{
				if (e.locked) { locked.add(e); lockedNames.add(e.entryName); }
				else            active.add(e);
			}

			if (!active.isEmpty())
			{
				entriesPanel.add(makeSectionHeader("ACTIVE TARGETS", COL_GOLD));
				for (CollectionSelectionPlugin.TargetEntry e : active) entriesPanel.add(makeEntryRow(e));
			}

			if (!locked.isEmpty())
			{
				entriesPanel.add(makeSectionHeader("LOCKED PAGES", COL_LOCKED_FG));
				for (CollectionSelectionPlugin.TargetEntry e : locked) entriesPanel.add(makeEntryRow(e));
			}

			entriesPanel.revalidate();
			entriesPanel.repaint();
		});
	}

	// ── Row helpers ───────────────────────────────────────────────────────────

	private JComponent makeSectionHeader(String text, Color accent)
	{
		JPanel hdr = new JPanel(new BorderLayout())
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setColor(COL_SECTION_BG);
				g2.fillRect(0, 0, getWidth(), getHeight());
				g2.setColor(accent);
				g2.fillRect(0, 0, 3, getHeight());
				g2.setColor(new Color(accent.getRed(), accent.getGreen(), accent.getBlue(), 60));
				g2.fillRect(0, getHeight() - 1, getWidth(), 1);
				g2.dispose();
			}
		};
		hdr.setOpaque(false);
		hdr.setMaximumSize(new Dimension(Integer.MAX_VALUE, 15));
		hdr.setPreferredSize(new Dimension(0, 15));

		JLabel lbl = new JLabel(text);
		lbl.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		lbl.setForeground(accent);
		lbl.setBorder(new EmptyBorder(0, 8, 0, 0));
		hdr.add(lbl, BorderLayout.CENTER);
		return hdr;
	}

	private JPanel makeEntryRow(CollectionSelectionPlugin.TargetEntry entry)
	{
		boolean locked = entry.locked;

		Color stripCol = locked ? COL_LOCKED_STRIP : COL_ACTIVE_STRIP;
		Color selectBg = locked ? COL_LOCKED_SEL   : COL_ACTIVE_SEL;
		Color entryFg  = locked ? COL_LOCKED_FG    : COL_ACTIVE_FG;

		JLabel iconLbl = new JLabel();
		if (locked && lockIconSmall != null) iconLbl.setIcon(lockIconSmall);
		iconLbl.setPreferredSize(new Dimension(12, 30));
		iconLbl.setVerticalAlignment(SwingConstants.CENTER);

		JLabel entryLbl = new JLabel(entry.entryName);
		entryLbl.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		entryLbl.setForeground(entryFg);

		JLabel itemLbl = new JLabel(entry.itemName);
		itemLbl.setFont(FontManager.getRunescapeSmallFont());
		itemLbl.setForeground(COL_ITEM_FG);

		JPanel text = new JPanel(new GridLayout(2, 1, 0, 0));
		text.setOpaque(false);
		text.add(entryLbl);
		text.add(itemLbl);

		JPanel row = new JPanel(new BorderLayout(5, 0));
		row.setOpaque(true);
		row.setBackground(COL_ROW);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createCompoundBorder(
				new MatteBorder(0, 3, 0, 0, stripCol),
				new MatteBorder(0, 0, 1, 0, COL_DIVIDER)
			),
			new EmptyBorder(3, 7, 3, 6)
		));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		row.setPreferredSize(new Dimension(0, 30));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.add(iconLbl, BorderLayout.WEST);
		row.add(text,    BorderLayout.CENTER);

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e) { selectRow(row, entry.entryName); }
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (row != selectedRow) { row.setBackground(COL_ROW_HOV); row.repaint(); }
			}
			@Override
			public void mouseExited(MouseEvent e)
			{
				if (row != selectedRow) { row.setBackground(COL_ROW); row.repaint(); }
			}
		});

		entryPanelMap.put(row, entry.entryName);
		return row;
	}

	private void selectRow(JPanel row, String entryName)
	{
		if (selectedRow != null)
		{
			selectedRow.setBackground(COL_ROW);
			selectedRow.repaint();
		}
		selectedRow       = row;
		selectedEntryName = entryName;
		row.setBackground(lockedNames.contains(entryName) ? COL_LOCKED_SEL : COL_ACTIVE_SEL);
		row.repaint();
	}

	// ── Button factory ────────────────────────────────────────────────────────

	private static JButton createButton(String text, Color base, Color hover)
	{
		JButton btn = new JButton(text)
		{
			@Override
			protected void paintComponent(Graphics g)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

				Color bg = !isEnabled()            ? COL_BTN_DISABLED
					     : getModel().isPressed()  ? base.darker()
					     : getModel().isRollover() ? hover
					     : base;

				g2.setColor(bg);
				g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 5, 5);

				if (isEnabled())
				{
					g2.setColor(new Color(255, 255, 255, 20));
					g2.fillRoundRect(0, 0, getWidth() - 1, (getHeight() - 1) / 2, 5, 5);
					g2.setColor(bg.darker());
				}
				else
				{
					g2.setColor(new Color(65, 65, 65));
				}
				g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 5, 5);
				g2.dispose();
				super.paintComponent(g);
			}

			@Override
			public void setEnabled(boolean b)
			{
				super.setEnabled(b);
				setForeground(b ? Color.WHITE : new Color(90, 90, 90));
				repaint();
			}
		};

		btn.setContentAreaFilled(false);
		btn.setBorderPainted(false);
		btn.setFocusPainted(false);
		btn.setForeground(Color.WHITE);
		btn.setFont(FontManager.getRunescapeSmallFont());
		btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		btn.setPreferredSize(new Dimension(0, 22));

		btn.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseEntered(MouseEvent e) { btn.repaint(); }
			@Override public void mouseExited(MouseEvent e)  { btn.repaint(); }
		});

		return btn;
	}
}

